<?php
$money = static fn($value) => 'R$ ' . number_format((float) $value, 2, ',', '.');
$statusLabels = ['pending'=>'Pendente','paid'=>'Paga','overdue'=>'Vencida','cancelled'=>'Cancelada','expected'=>'Prevista','received'=>'Recebida','late'=>'Atrasada'];
$typeLabels = ['income'=>'Receita','expense'=>'Despesa','transfer'=>'Transferência'];
$query = static fn(array $extra = []) => http_build_query(array_filter(array_merge($filters, $extra), static fn($v) => $v !== '' && $v !== null));
?>
<section class="hero-row compact-hero"><div><span class="eyebrow">Controle financeiro</span><h2 class="page-heading">Lançamentos</h2><p class="page-subtitle">Tudo o que entra e sai, em um só lugar.</p></div><div class="hero-actions"><a class="button button-ghost" href="/lancamentos/importar">Lançar em lote</a><a class="button button-primary" href="/lancamentos/novo"><span>+</span> Novo lançamento</a><a class="button button-ghost" href="/transferencias/nova">Transferir</a></div></section>
<form method="get" class="filter-card"><label class="search-field"><span class="search-icon">⌕</span><input type="search" name="search" value="<?= htmlspecialchars($filters['search'] ?? '') ?>" placeholder="Buscar por descrição..."></label><select name="type"><option value="">Todos os tipos</option><option value="income" <?= ($filters['type'] ?? '') === 'income' ? 'selected' : '' ?>>Receitas</option><option value="expense" <?= ($filters['type'] ?? '') === 'expense' ? 'selected' : '' ?>>Despesas</option><option value="transfer" <?= ($filters['type'] ?? '') === 'transfer' ? 'selected' : '' ?>>Transferências</option></select><select name="status"><option value="">Todos os status</option><?php foreach ($statusLabels as $key => $label): ?><option value="<?= $key ?>" <?= ($filters['status'] ?? '') === $key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select><select name="account_id"><option value="">Todas as contas</option><?php foreach ($accounts as $account): ?><option value="<?= (int) $account->id ?>" <?= ((int) ($filters['account_id'] ?? 0) === (int) $account->id) ? 'selected' : '' ?>><?= htmlspecialchars($account->name) ?></option><?php endforeach; ?></select><select name="cost_center_id"><option value="">Todos os centros</option><?php $selected = (int) ($filters['cost_center_id'] ?? 0); require __DIR__ . '/_cost_center_options.php'; ?></select><button class="button button-secondary" type="submit">Filtrar</button><?php if (!empty($filters['center_kind'])): ?><input type="hidden" name="center_kind" value="<?= htmlspecialchars($filters['center_kind']) ?>"><?php endif; ?><a class="clear-filter <?= ($filters['center_kind'] ?? '') === 'property' ? 'active' : '' ?>" href="/lancamentos?<?= $query(['center_kind' => ($filters['center_kind'] ?? '') === 'property' ? null : 'property']) ?>">🏠 Somente imóveis</a><?php if ($filters): ?><a class="clear-filter" href="/lancamentos">Limpar</a><?php endif; ?></form>
<section class="panel transactions-panel"><div class="panel-heading"><div><span class="eyebrow">Histórico</span><h3><?= count($transactions) ?> nesta página</h3></div><span class="muted-text">Página <?= (int) $page ?> de <?= (int) $pages ?></span></div><?php if (!$transactions): ?><div class="empty-state"><span class="empty-icon">◌</span><h3>Nenhum lançamento encontrado</h3><p>Comece registrando sua primeira receita ou despesa.</p><a class="button button-primary" href="/lancamentos/novo">Adicionar lançamento</a></div><?php else: ?><div class="transaction-table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Conta</th><th>Status</th><th class="align-right">Valor</th><th></th></tr></thead><tbody><?php foreach ($transactions as $item): ?><tr><td data-label="Data"><?= date('d/m/Y', strtotime($item->transaction_date)) ?></td><td data-label="Descrição"><div class="transaction-name"><span class="type-dot <?= htmlspecialchars($item->type) ?>"></span><strong><?= htmlspecialchars($item->description) ?></strong><?php if ($item->type === 'transfer'): ?><small>Movimentação interna</small><?php endif; ?><?php if (!empty($item->cost_center_name)): ?><small class="transaction-center"><?= ($item->cost_center_kind ?? '') === 'property' ? '🏠' : '🏷️' ?> <?= htmlspecialchars($item->cost_center_name) ?></small><?php endif; ?><?php if (!empty($item->attachment_path)): ?><a class="attach-link" href="/lancamentos/<?= (int) $item->id ?>/anexo" target="_blank" rel="noopener" title="Ver anexo">📎</a><?php endif; ?></div></td><td data-label="Categoria"><?= htmlspecialchars($item->category_name ?? '—') ?></td><td data-label="Conta"><?= htmlspecialchars($item->account_name) ?></td><td data-label="Status"><span class="status-badge status-<?= htmlspecialchars($item->status) ?>"><?= htmlspecialchars($statusLabels[$item->status] ?? $item->status) ?></span></td><td data-label="Valor" class="align-right amount <?= $item->type === 'income' ? 'positive' : ($item->type === 'expense' ? 'negative' : '') ?>"><?= $item->type === 'income' ? '+' : ($item->type === 'expense' ? '-' : '') ?><?= $money($item->amount) ?></td><td class="row-actions"><a class="action-link" href="/lancamentos/<?= (int) $item->id ?>/editar">Editar</a><details class="action-menu"><summary>•••</summary><div class="action-popover"><form method="post" action="/lancamentos/<?= (int) $item->id ?>/duplicar"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><button type="submit">Duplicar</button></form><?php if ($item->type !== 'transfer'): ?><form method="post" action="/lancamentos/<?= (int) $item->id ?>/status"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><input type="hidden" name="status" value="<?= $item->type === 'income' ? 'received' : 'paid' ?>"><button type="submit">Marcar como <?= $item->type === 'income' ? 'recebida' : 'paga' ?></button></form><?php endif; ?><form method="post" action="/lancamentos/<?= (int) $item->id ?>/excluir" data-confirm="Excluir este lançamento?"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><button type="submit" class="danger-text">Excluir</button></form></div></details></td></tr><?php endforeach; ?></tbody></table></div><div class="pagination"><?php if ($page > 1): ?><a href="/lancamentos?<?= $query(['page' => $page - 1]) ?>">‹ Anterior</a><?php endif; ?><span><?= (int) $page ?> / <?= (int) $pages ?></span><?php if ($page < $pages): ?><a href="/lancamentos?<?= $query(['page' => $page + 1]) ?>">Próxima ›</a><?php endif; ?></div><?php endif; ?></section>
